34:private func inspectCounter(_ bank: borrowing SemanticRecordView<CounterPayload>, value: UInt8) -> (SemanticCompleteIdentity, Int) {
35:    var checks = 0, textCount = 0, actionCount = 0, disabledCount = 0, canvasCount = 0
36:    var modelIdentity: SemanticCompleteIdentity?
37:    for index: UInt16 in 0..<bank.recordCount {
38:        let ref = bank.reference(at: index)!
39:        let record = bank.record(ref)!
40:        if bank.path(at: record.path)?.component.role == 1 {
41:            var target = bank.completeIdentity(for: ref)!
42:            // visitCustomBody enters customBody before evaluateStateful binds
43:            // State; this is the owning declaration identity, not its record key.
44:            counterSemanticExpect(target.append(.init(kind: .customBody)))
45:            modelIdentity = target
46:        }
47:        guard let payload = bank.payload(at: record.payload) else { continue }
48:        switch payload {
49:        case .canvas:
50:            canvasCount += 1
51:        case .standard(.text):
52:            let expected: InlineArray<9, UInt32> = textCount == 0 ? [67,111,117,110,116,101,114,0,0] : textCount == 1 ? [UInt32(48 + value),0,0,0,0,0,0,0,0] : textCount == 2 ? [73,110,99,114,101,109,101,110,116] : [82,101,115,101,116,0,0,0,0]
53:            let count: UInt16 = textCount == 0 ? 7 : textCount == 1 ? 1 : textCount == 2 ? 9 : 5
54:            counterSemanticExpect(record.textScalarCount == count); checks += 1
55:            for scalar: UInt16 in 0..<count { counterSemanticExpect(bank.scalar(at: record.firstTextScalar + scalar) == expected[Int(scalar)]); checks += 1 }
56:            textCount += 1
57:        case .standard(.action(let role, let code)):
58:            counterSemanticExpect(role == 6 && code == UInt16(actionCount)); actionCount += 1; checks += 1
59:        case .standard(.disabled(let disabled)):
60:            counterSemanticExpect(disabled == (disabledCount == 0 ? value == 9 : value == 0)); disabledCount += 1; checks += 1
61:        default: break
62:        }
63:    }
64:    counterSemanticExpect(textCount == 4 && actionCount == 2 && disabledCount == 2 && canvasCount == 1); checks += 1
65:    counterSemanticExpect(bank.recordCount <= 64 && bank.pathCount <= 192 && bank.payloadBytes <= 4096); checks += 1
66:    return (modelIdentity!, checks)
67:}
